FUNCTION first_batch RETURN NUMBER IS
  TYPE batch_t IS TABLE OF NUMBER;
  l_batch batch_t;
BEGIN
  l_batch.EXTEND;
  l_batch(1) := 17;
  RETURN l_batch(1);
END first_batch;

PROCEDURE normalize_tag(p_tag IN VARCHAR2) IS
BEGIN
  p_tag := UPPER(TRIM(p_tag));
  DBMS_OUTPUT.PUT_LINE(p_tag);
END normalize_tag;

CREATE OR REPLACE TRIGGER parcel_limit
BEFORE INSERT ON parcels FOR EACH ROW
DECLARE
  l_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO l_count FROM parcels WHERE route_id = :NEW.route_id;
  IF l_count >= 50 THEN
    RAISE_APPLICATION_ERROR(-20351, 'route capacity');
  END IF;
END;

FUNCTION sensor_value RETURN NUMBER IS
  CURSOR c IS SELECT 23 AS reading FROM dual;
  l_value NUMBER;
BEGIN
  FETCH c INTO l_value;
  CLOSE c;
  RETURN l_value;
END sensor_value;

FUNCTION clamp_nonnegative(p_value NUMBER) RETURN NUMBER IS
BEGIN
  RETURN CASE WHEN p_value < 0 THEN 0 ELSE p_value END;
END clamp_nonnegative;

FUNCTION safe_ratio(p_n NUMBER, p_d NUMBER) RETURN NUMBER IS
  l_value NUMBER;
BEGIN
  RETURN p_n / p_d;
END safe_ratio;
